//! The curated seed table. Generated by `cargo xtask-art curated-seeds` (decision T-49); do not edit
//! by hand. Empty until the generator has run.

use super::PER_LEVEL;
use crate::game::Variant;

/// Three seeds for each of the five levels, easiest first.
pub(super) type Levels = [[u64; PER_LEVEL]; 5];

const TABLE: &[(Variant, Levels)] = &[];

/// The levels of `variant`, when the table has them.
pub(super) fn levels(variant: Variant) -> Option<&'static Levels> {
    TABLE
        .iter()
        .find(|(entry, _)| *entry == variant)
        .map(|(_, levels)| levels)
}
